while q:
 r,c=q.popleft()
 for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
  if 0<=nr<h and 0<=nc<w and a[nr][nc]==0 and (nr,nc) not in seen: seen.add((nr,nc));q.append((nr,nc))
out=[row[:] for row in a]
for r,c in seen:
 if out[r][c]==0:out[r][c]=5
print('\n'.join(' '.join(map(str,row)) for row in out))

